    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.imageSmoothingEnabled = false;

    // Game variables
    let isRunning = true;
    let animId: number;
    let score = 0;
    let lives = 3;

    // Keys
    const keys: Record<string, boolean> = {};
